-- Expanded Psionics Handbook powers G-L.
-- Concise mechanical summaries; XPH remains the source of record.

WITH desired(slug,name,discipline,subdiscipline,manifesting_time,action_type,range_text,target_text,area_text,effect_text,duration_text,save,saving_throw_text,power_resistance,power_resistance_text,power_points,description,augmentation_text) AS (VALUES
('genesis','Genesis','metacreativity','creation','One week (8 hours/day)','other','180 ft.; see text',NULL,NULL,'A demiplane coterminous with the Astral Plane, centered on your location','Instantaneous',NULL,'None','no',NULL,17,'Create and define the environment of a small demiplane; when manifested on the Material Plane the power instead creates the book’s limited antigenesis dead zone.','XP cost: 1,000 XP.'),
('graft-weapon','Graft Weapon','psychometabolism',NULL,'1 standard action','standard','Personal','You',NULL,NULL,'24 hours (D)',NULL,NULL,'no',NULL,5,'Graft a one-handed melee weapon onto an arm, gaining a +1 competence bonus on attack and damage rolls with it while it counts as both a manufactured and natural weapon.',NULL),
('grease-psionic','Grease, Psionic','metacreativity','creation','1 standard action','standard','Close (25 ft. + 5 ft./2 levels)',NULL,'One object or a 10-ft. square',NULL,'1 round/level (D)',NULL,'See spell text','no',NULL,1,'Create the effect of the grease spell psionically; the power is also known as ectoplasmic sheen.',NULL),
('grip-of-iron','Grip of Iron','psychometabolism',NULL,'1 immediate action','immediate','Personal','You',NULL,NULL,'1 round/level',NULL,NULL,'no',NULL,1,'Immediately gain a +4 enhancement bonus on grapple checks.','For every 4 additional power points, increase the grapple bonus by 2.'),
('hail-of-crystals','Hail of Crystals','metacreativity','creation','1 standard action','standard','Medium (100 ft. + 10 ft./level)',NULL,'20-ft.-radius burst',NULL,'Instantaneous','ref','Reflex half','no',NULL,9,'Launch a crystal that can deal 5d4 bludgeoning damage to a directly struck target before exploding for 9d4 slashing damage in a 20-foot burst.','Each additional power point increases the explosion damage by 1d4.'),
('hammer','Hammer','psychometabolism',NULL,'1 standard action','standard','Personal','You',NULL,NULL,'1 round',NULL,NULL,'no',NULL,1,'Charge your touch so a successful melee touch attack deals 1d8 bludgeoning damage without a Strength modifier.','Each additional power point increases duration by 1 round.'),
('hustle','Hustle','psychometabolism',NULL,'1 swift action','swift','Personal','You',NULL,'1 extra move action','Instantaneous',NULL,NULL,'no',NULL,3,'Gain one additional move action in the current round.','Egoist base cost is 5 PP; psychic warrior base cost is 3 PP.'),
('hypercognition','Hypercognition','clairsentience',NULL,'1 standard action or 1 immediate action; see text','other','Personal','You',NULL,NULL,'Instantaneous',NULL,NULL,'no',NULL,15,'Force rapid logical deduction from available clues and memory; when used immediately before the relevant Intelligence check, gain the power’s +20 bonus.',NULL),
('id-insinuation','Id Insinuation','telepathy','compulsion','1 standard action','standard','Close (25 ft. + 5 ft./2 levels)','One creature',NULL,NULL,'Concentration + 1 round','will','Will negates','yes',NULL,3,'Disrupt a creature’s unconscious mind, leaving it confused while you concentrate and for 1 round afterward.','For every 2 additional power points, increase save DC by 1 and affect one additional nearby target.'),
('identify-psionic','Identify, Psionic','clairsentience',NULL,'One day','other','Touch','One touched object',NULL,NULL,'Instantaneous',NULL,'None','no',NULL,3,'Identify the abilities of a psionic item as the identify spell does for magic items.',NULL),
('immovability','Immovability','psychometabolism',NULL,'1 standard action','standard','Personal','You',NULL,NULL,'Concentration',NULL,NULL,'no',NULL,7,'Anchor yourself to the fabric of the plane, gaining +20 on opposed Strength checks to resist movement and DR 15/— while severely restricting your own physical movement.','Spend 8 additional power points to manifest as an immediate action.'),
('incarnate','Incarnate','metacreativity',NULL,'2 rounds','other','See text','See text','See text','See text','Permanent; see text',NULL,'None','no',NULL,9,'Make one of the specific powers listed by incarnate permanent when its minimum manifester-level and XP requirements are met.','XP cost varies with the power made permanent.'),
('inertial-armor','Inertial Armor','psychokinesis',NULL,'1 standard action','standard','Personal','You',NULL,NULL,'1 hour/level (D)',NULL,NULL,'no',NULL,1,'Create a tangible field of force that grants a +4 armor bonus to Armor Class.','For every 2 additional power points, increase the armor bonus by 1.'),
('inertial-barrier','Inertial Barrier','psychokinesis',NULL,'1 standard action','standard','Personal','You',NULL,NULL,'10 min./level',NULL,NULL,'no',NULL,7,'Surround yourself with an inertial field that grants DR 5/— and halves damage from falls and similar impacts.',NULL),
('inflict-pain','Inflict Pain','telepathy',NULL,'1 standard action','standard','Close (25 ft. + 5 ft./2 levels)','One creature',NULL,NULL,'1 round/level','will','Will partial','yes',NULL,3,'Flood the subject with pain, imposing a –4 penalty on attack rolls, skill checks, and ability checks; a successful save reduces the penalty to –2.','For every 2 additional power points, increase save DC by 1 and affect one additional nearby target.'),
('insanity','Insanity','telepathy','compulsion','1 standard action','standard','Medium (100 ft. + 10 ft./level)','One creature',NULL,NULL,'Instantaneous','will','Will negates','yes',NULL,13,'Permanently confuse a creature that fails its Will save.','For every 2 additional power points, increase save DC by 1 and affect one additional nearby target.'),
('intellect-fortress','Intellect Fortress','psychokinesis',NULL,'1 immediate action','immediate','20 ft.',NULL,'20-ft.-radius spread centered on you',NULL,'1 round',NULL,'None','yes',NULL,7,'Immediately create a mental fortress that halves hit point and ability damage from powers and psi-like abilities for creatures in the area.','Each additional power point increases duration by 1 round.'),
('iron-body-psionic','Iron Body, Psionic','metacreativity','creation','1 standard action','standard','Personal','You',NULL,NULL,'1 min./level (D)',NULL,NULL,'no',NULL,15,'Gain the effects of the iron body spell psionically.',NULL),
('keen-edge-psionic','Keen Edge, Psionic','metacreativity',NULL,'1 standard action','standard','Close (25 ft. + 5 ft./2 levels)','One weapon or fifty projectiles, all in contact at manifestation',NULL,NULL,'10 min./level','will','Will negates (harmless, object)','yes','Yes (harmless, object)',5,'Increase the threat range of a qualifying weapon or group of projectiles as the keen edge spell.',NULL),
('knock-psionic','Knock, Psionic','psychoportation',NULL,'1 standard action','standard','Medium (100 ft. + 10 ft./level)','One door, box, or chest with an area up to 10 sq. ft./level',NULL,NULL,'Instantaneous; see spell text',NULL,'None','no',NULL,3,'Open stuck, barred, locked, held, or otherwise secured doors and containers as the knock spell.',NULL),
('know-direction-and-location','Know Direction and Location','clairsentience',NULL,'1 standard action','standard','Personal','You',NULL,NULL,'Instantaneous',NULL,NULL,'no',NULL,1,'Determine your general location and facing and gain the stated navigational benefit when using astral caravan.',NULL),
('leech-field','Leech Field','psychometabolism',NULL,'1 standard action','standard','Personal; see text','You',NULL,NULL,'1 min.',NULL,NULL,'no',NULL,9,'Create a field that lets you gain power points after successfully saving against qualifying single-target powers, subject to your normal reserve limit.','For every 2 additional power points, increase duration by 1 minute.'),
('levitate-psionic','Levitate, Psionic','psychoportation',NULL,'1 standard action','standard','Personal or close; see text','You, one willing creature, or one object; see text',NULL,NULL,'10 min./level (D)','will','Will negates (harmless, object)','yes','Yes (harmless, object)',3,'Levitate yourself, a willing creature, or an object as the levitate spell, subject to the class-specific targeting restriction.',NULL)
)
INSERT INTO dnd35_powers
(id,source_id,source_page,slug,name,description,rules_text,is_homebrew,owner_user_id,is_enabled,discipline_id,subdiscipline,manifesting_time,action_type,range_text,target_text,area_text,effect_text,duration_text,save,saving_throw_text,power_resistance,power_resistance_text,power_points,augmentation_text,augmentation)
SELECT
  'xph-power-'||d.slug,'xph-3.5','Chapter 5',d.slug,d.name,d.description,d.description,0,NULL,1,
  'xph-power-discipline-'||d.discipline,d.subdiscipline,d.manifesting_time,d.action_type,d.range_text,
  d.target_text,d.area_text,d.effect_text,d.duration_text,d.save,d.saving_throw_text,
  d.power_resistance,d.power_resistance_text,d.power_points,d.augmentation_text,NULL
FROM desired d
WHERE NOT EXISTS (
  SELECT 1 FROM dnd35_powers p
  WHERE p.slug=d.slug AND p.owner_user_id IS NULL
);
